MonarchAiPromptInput(
    label = "Message the assistant",
    state = prompt,
    onSubmit = { files = emptyList() },
    attachments = files,
    onAttach = {
        // Launch PickVisualMedia and add the picked files.
    },
    onReceiveFiles = { uris ->
        files = files + uris.map { MonarchAiAttachmentTrayFile(it.toString(), it.lastPathSegment ?: "image") }
    },
    onRemoveAttachment = { id -> files = files.filterNot { it.id == id } },
)
